import bcrypt from "bcryptjs";
import { SignJWT, jwtVerify } from "jose";

export const hashPassword = (pw: string) => bcrypt.hash(pw, 10);
export const checkPassword = (pw: string, hash: string) => bcrypt.compare(pw, hash);

export async function createSession(userId: string, secret: Uint8Array, ttl = "2h") {
  return new SignJWT({ role: "user" })
    .setProtectedHeader({ alg: "HS256" })
    .setSubject(userId)
    .setIssuedAt()
    .setIssuer("my-app")
    .setExpirationTime(ttl)
    .sign(secret);
}

export async function readSession(token: string, secret: Uint8Array) {
  const { payload } = await jwtVerify(token, secret, { issuer: "my-app", algorithms: ["HS256"] });
  return { userId: payload.sub!, role: payload.role as string };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { hashPassword, checkPassword, createSession, readSession } from "../src/auth.ts";

const secret = new TextEncoder().encode("a-32-byte-long-test-secret-value!");

test("hash and verify a password", async () => {
  const h = await hashPassword("hunter2");
  assert.notEqual(h, "hunter2");
  assert.equal(await checkPassword("hunter2", h), true);
  assert.equal(await checkPassword("wrong", h), false);
});

test("session round trip", async () => {
  const t = await createSession("u1", secret);
  assert.deepEqual(await readSession(t, secret), { userId: "u1", role: "user" });
});

test("rejects tampered and expired tokens", async () => {
  const t = await createSession("u1", secret);
  await assert.rejects(readSession(t, new TextEncoder().encode("another-32-byte-long-secret-val!!")));
  const old = await createSession("u1", secret, "-1s");
  await assert.rejects(readSession(old, secret));
});

from celery import Celery, chain, group

app = Celery("tasks", broker="memory://", backend="cache+memory://")

@app.task
def add(x, y):
    return x + y

@app.task
def double(x):
    return x * 2

def add_then_double(x, y):
    return chain(add.s(x, y), double.s())

def sum_of_doubles(nums):
    # fan out with a group, then reduce the results
    return sum(group(double.s(n) for n in nums).apply_async().get())

import pytest
from tasks import app, add, add_then_double, sum_of_doubles

@pytest.fixture(autouse=True)
def eager():
    app.conf.update(task_always_eager=True, task_eager_propagates=True)
    yield
    app.conf.update(task_always_eager=False)

def test_delay():
    assert add.delay(2, 3).get() == 5

def test_chain():
    assert add_then_double(2, 3).apply_async().get() == 10

def test_group():
    assert sum_of_doubles([1, 2, 3]) == 12

def test_errors_propagate():
    with pytest.raises(TypeError):
        add.delay(1, "a").get()

from rest_framework import serializers
from .models import Book

class BookSerializer(serializers.ModelSerializer):
    class Meta:
        model = Book
        fields = ["id", "title", "isbn", "published"]

    def validate_isbn(self, value):
        if not value.isdigit() or len(value) not in (10, 13):
            raise serializers.ValidationError("ISBN must be 10 or 13 digits")
        return value

